<?php if ($can_review_grades): ?><section class="card border-0 shadow-sm mb-4"><div class="card-header bg-white"><h2 class="h6 fw-bold mb-0">Grades awaiting review</h2></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Student</th><th>School year / Grade</th><th>Subject</th><th>Grades: prelim / midterm / finals / final</th><th>Decision</th></tr></thead><tbody>
<?php if (!$grade_queue): ?><tr><td colspan="5" class="text-center text-secondary py-4">No grades are awaiting review.</td></tr><?php else: foreach ($grade_queue as $grade): ?><tr><td><?= html_escape(trim($grade->first_name . ' ' . $grade->middle_name . ' ' . $grade->last_name)); ?><div class="small text-secondary"><?= html_escape($grade->student_no); ?></div></td><td><?= html_escape($grade->academic_year); ?><div class="small text-secondary"><?= html_escape($grade->grade_level); ?></div></td><td><?= html_escape($grade->subject_name); ?></td><td><?= html_escape(implode(' / ', array_map(function ($field) use ($grade) { return $grade->{$field} === null ? '—' : number_format((float) $grade->{$field}, 2); }, ['prelim_grade', 'midterm_grade', 'finals_grade', 'final_grade']))); ?></td><td><form method="post" action="<?= site_url('academic/review/grade'); ?>" class="d-flex flex-wrap gap-2"><input type="hidden" name="<?= html_escape($this->security->get_csrf_token_name()); ?>" value="<?= html_escape($this->security->get_csrf_hash()); ?>"><input type="hidden" name="grade_id" value="<?= (int) $grade->id; ?>"><input class="form-control form-control-sm" name="review_note" maxlength="500" placeholder="Required when returning"><button class="btn btn-sm btn-success" name="decision" value="approved">Approve</button><button class="btn btn-sm btn-outline-danger" name="decision" value="returned">Return</button></form></td></tr><?php endforeach; endif; ?>
</tbody></table></div></section><?php endif; ?>
<?php if ($can_review_grades): ?><section class="card border-0 shadow-sm mb-4"><div class="card-header bg-white"><h2 class="h6 fw-bold mb-0">Grade correction requests</h2></div><div class="card-body">
