<?php if (!$gradeCorrections): ?><p class="text-secondary mb-0">No approved-grade corrections are awaiting review.</p><?php else: foreach ($gradeCorrections as $request): $context = $correction_context($request); $proposed = json_decode($request->proposed_values, true) ?: []; ?>
<div class="border rounded p-3 mb-3"><div class="fw-semibold"><?= html_escape($context ? trim($context->first_name . ' ' . $context->last_name) . ' · ' . $context->subject_name : 'Grade correction request'); ?></div><div class="small text-secondary mb-2">Reason: <?= html_escape($request->reason); ?></div><div class="small mb-2">Proposed final grade: <?= html_escape($proposed['final_grade'] ?? '—'); ?></div><form method="post" action="<?= site_url('academic/review/correction'); ?>" class="d-flex flex-wrap gap-2"><input type="hidden" name="<?= html_escape($this->security->get_csrf_token_name()); ?>" value="<?= html_escape($this->security->get_csrf_hash()); ?>"><input type="hidden" name="request_id" value="<?= (int) $request->id; ?>"><input class="form-control form-control-sm" name="review_note" maxlength="500" placeholder="Required when rejecting"><button class="btn btn-sm btn-success" name="decision" value="approved">Approve correction</button><button class="btn btn-sm btn-outline-danger" name="decision" value="rejected">Reject</button></form></div>
<?php endforeach; endif; ?></div></section><?php endif; ?>
